namespace TerraBase.Protocol;

/// <summary>
/// The hand-written half of the generated registry: lookups over the
/// committed frame table. The generated half
/// (<c>Generated/TbepRegistry.g.cs</c>) is regenerated by
/// <c>crates/terrabase-tbep/tools/tbep-gen</c> from the shared schema —
/// one source of truth, both languages, drift-checked by the Rust test
/// suite (<c>tests/registry_drift.rs</c>).
/// </summary>
public static partial class TbepRegistry
{
    /// <summary>Compares one field of two generated bodies: scalars by value, strings ordinally, arrays element-wise.</summary>
    /// <typeparam name="T">The field type.</typeparam>
    /// <param name="left">The left value.</param>
    /// <param name="right">The right value.</param>
    /// <returns>True when the fields are equal.</returns>
    public static bool FieldEquals<T>(T? left, T? right)
    {
        if (ReferenceEquals(left, right))
        {
            return true;
        }

        if (left is null || right is null)
        {
            return false;
        }

        return (left, right) switch
        {
            (string a, string b) => string.Equals(a, b, StringComparison.Ordinal),
            (byte[] a, byte[] b) => a.AsSpan().SequenceEqual(b),
            (System.Collections.IEnumerable a, System.Collections.IEnumerable b) => SequenceEquals(a, b),
            _ => left.Equals(right),
        };
    }

    private static bool SequenceEquals(System.Collections.IEnumerable left, System.Collections.IEnumerable right)
    {
        var first = left.GetEnumerator();
        var second = right.GetEnumerator();
        while (first.MoveNext())
        {
            if (!second.MoveNext() || !Equals(first.Current, second.Current))
            {
                return false;
            }
        }

        return !second.MoveNext();
    }

    /// <summary>Answers whether a kind code exists in the closed registry.</summary>
    /// <param name="kind">The kind code.</param>
    /// <returns>True when the code is registered.</returns>
    public static bool KnowsKind(ushort kind) => Frames.Any(row => row.Code == kind);

    /// <summary>Answers whether a kind carries an idempotency key (mutation-family request frames).</summary>
    /// <param name="kind">The kind code.</param>
    /// <returns>True when the pairing requires a key.</returns>
    public static bool CarriesIdempotency(ushort kind) =>
        Frames.Any(row => row.Code == kind && row.CarriesIdempotency);

    /// <summary>The registry name of a kind code.</summary>
    /// <param name="kind">The kind code.</param>
    /// <returns>The PascalCase kind name.</returns>
    /// <exception cref="TbepWire.WireException">The code is not registered.</exception>
    public static string KindName(ushort kind) =>
        (from row in Frames where row.Code == kind select row.Kind).FirstOrDefault()
            ?? throw TbepWire.FormatException($"unknown frame kind {kind}", TbepWire.WireFailure.UnknownFrameKind);

    /// <summary>The kind code of a registry name.</summary>
    /// <param name="name">The PascalCase kind name.</param>
    /// <returns>The kind code.</returns>
    /// <exception cref="TbepWire.WireException">The name is not registered.</exception>
    public static ushort KindCode(string name) =>
        (from row in Frames where row.Kind == name select (ushort?)row.Code).FirstOrDefault()
            ?? throw TbepWire.FormatException($"unknown frame kind {name}", TbepWire.WireFailure.UnknownFrameKind);

    /// <summary>The request kind code of an operation name.</summary>
    /// <param name="operation">The dotted operation name (for example <c>document.read</c>).</param>
    /// <returns>The request kind code.</returns>
    /// <exception cref="TbepWire.WireException">The operation is not registered.</exception>
    public static ushort RequestKindOf(string operation) =>
        (from row in Operations where row.Name == operation select (ushort?)row.RequestCode).FirstOrDefault()
            ?? throw TbepWire.FormatException($"unknown operation {operation}", TbepWire.WireFailure.UnknownFrameKind);

    /// <summary>The response kind code of an operation name.</summary>
    /// <param name="operation">The dotted operation name.</param>
    /// <returns>The response kind code.</returns>
    /// <exception cref="TbepWire.WireException">The operation is not registered.</exception>
    public static ushort ResponseKindOf(string operation) =>
        (from row in Operations where row.Name == operation select (ushort?)row.ResponseCode).FirstOrDefault()
            ?? throw TbepWire.FormatException($"unknown operation {operation}", TbepWire.WireFailure.UnknownFrameKind);
}
